/* ============================================================
   GreenBean Coffee — Global Styles
   ============================================================ */

@import url('https://fonts.googleapis.com/css2?family=DM+Serif+Display:ital@0;1&family=DM+Sans:wght@300;400;500;600;700&display=swap');

/* ── Variables ─────────────────────────────────────────────── */
:root {
  --green:        #00824A;
  --green-dark:   #006d3e;
  --green-light:  #e6f4ee;
  --forest:       #32462F;
  --forest-dark:  #253d22;
  --cream:        #F3CEA1;
  --cream-light:  #FDF6EE;
  --cream-mid:    #f5ddb8;
  --brown:        #6F4E37;
  --brown-light:  #c8a882;
  --white:        #FFFFFF;
  --text:         #1a1a1a;
  --text-mid:     #4a4a4a;
  --text-light:   #767676;
  --border:       #e5e0d8;
  --shadow-sm:    0 2px 8px rgba(0,0,0,0.07);
  --shadow-md:    0 4px 20px rgba(0,0,0,0.10);
  --shadow-lg:    0 8px 40px rgba(0,0,0,0.14);
  --r-sm:  8px;
  --r-md:  16px;
  --r-lg:  24px;
  --r-xl:  40px;
  --ease: 0.22s ease;
  --font-head: 'DM Serif Display', Georgia, serif;
  --font-body: 'DM Sans', system-ui, sans-serif;
}

/* ── Reset ─────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; font-size: 16px; }
body { font-family: var(--font-body); color: var(--text); background: var(--white); line-height: 1.6; -webkit-font-smoothing: antialiased; }
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; border: none; background: none; font-family: inherit; font-size: inherit; }
ul, ol { list-style: none; }
input, textarea { font-family: inherit; font-size: inherit; }
svg { display: block; }

/* ── Typography ────────────────────────────────────────────── */
h1, h2, h3, h4, h5 { font-family: var(--font-head); line-height: 1.15; }
h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.6rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.875rem); }
h4 { font-size: 1.25rem; }
p { line-height: 1.75; }

/* ── Layout ────────────────────────────────────────────────── */
.container      { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.container--wide { max-width: 1440px; margin: 0 auto; padding: 0 32px; }

/* ── Buttons ───────────────────────────────────────────────── */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 13px 28px; border-radius: var(--r-xl);
  font-weight: 700; font-size: 0.9375rem; font-family: var(--font-body);
  transition: all var(--ease); white-space: nowrap; cursor: pointer;
  line-height: 1; border: 2px solid transparent;
}
.btn--primary  { background: var(--green); color: var(--white); }
.btn--primary:hover  { background: var(--green-dark); transform: translateY(-2px); box-shadow: 0 6px 20px rgba(0,130,74,0.35); }
.btn--outline  { background: transparent; color: var(--green); border-color: var(--green); }
.btn--outline:hover  { background: var(--green); color: var(--white); }
.btn--dark     { background: var(--forest); color: var(--white); }
.btn--dark:hover     { background: var(--forest-dark); transform: translateY(-2px); }
.btn--white    { background: var(--white); color: var(--forest); }
.btn--white:hover    { background: var(--cream-light); transform: translateY(-2px); }
.btn--cream    { background: var(--cream); color: var(--forest); border-color: var(--cream); }
.btn--cream:hover    { background: var(--cream-mid); transform: translateY(-2px); }
.btn--outline-white { background: transparent; color: var(--white); border-color: rgba(255,255,255,0.7); }
.btn--outline-white:hover { background: rgba(255,255,255,0.15); }
.btn--sm  { padding: 9px 18px; font-size: 0.875rem; }
.btn--lg  { padding: 16px 36px; font-size: 1.0625rem; }
.btn--icon { padding: 12px; border-radius: 50%; }

/* ── Sections ──────────────────────────────────────────────── */
.section { padding: 80px 0; }
.section--sm { padding: 48px 0; }
.section--lg { padding: 112px 0; }
.section--cream { background: var(--cream-light); }
.section--forest { background: var(--forest); color: var(--white); }
.section--green { background: var(--green); color: var(--white); }
.section-label {
  display: inline-block; font-size: 0.75rem; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.1em; color: var(--green);
  margin-bottom: 10px;
}
.section-label--light { color: var(--cream); }
.section-header { text-align: center; margin-bottom: 56px; }
.section-header p { color: var(--text-mid); max-width: 560px; margin: 12px auto 0; }
.section-header--light p { color: rgba(255,255,255,0.75); }
.section-header--left { text-align: left; }
.section-header--left p { margin-left: 0; }

/* ── Cards ─────────────────────────────────────────────────── */
.card {
  background: var(--white); border-radius: var(--r-lg);
  box-shadow: var(--shadow-sm); overflow: hidden;
  transition: transform var(--ease), box-shadow var(--ease);
}
.card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.card-img { width: 100%; aspect-ratio: 4/3; overflow: hidden; }
.card-body { padding: 20px; }
.card-title { font-size: 1rem; font-weight: 600; margin-bottom: 4px; }
.card-desc { font-size: 0.875rem; color: var(--text-mid); }

/* ── Badges ─────────────────────────────────────────────────── */
.badge {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 4px 12px; border-radius: var(--r-xl);
  font-size: 0.75rem; font-weight: 700; letter-spacing: 0.03em;
}
.badge--green  { background: var(--green-light); color: var(--green-dark); }
.badge--cream  { background: var(--cream); color: var(--forest); }
.badge--forest { background: var(--forest); color: var(--white); }
.badge--new    { background: #FFF0D4; color: #A05C00; }

/* ── Image Placeholders ─────────────────────────────────────── */
.img-ph {
  width: 100%; height: 100%; min-height: 200px;
  display: flex; align-items: center; justify-content: center;
  font-size: 3.5rem; border-radius: inherit;
}
.img-ph--hero       { background: linear-gradient(135deg, #1a3a2a 0%, #2d5a3d 50%, #00824A 100%); }
.img-ph--citrus     { background: linear-gradient(135deg, #ff9b00 0%, #ffcc44 60%, #ffe580 100%); }
.img-ph--afternoon  { background: linear-gradient(135deg, #6F4E37 0%, #c8956c 60%, #f3cea1 100%); }
.img-ph--ai         { background: linear-gradient(135deg, #1a3a5c 0%, #2d6a9f 100%); }
.img-ph--mango      { background: linear-gradient(135deg, #f7a800 0%, #ff6b35 60%, #ffcc44 100%); }
.img-ph--spring     { background: linear-gradient(135deg, #7c4dbe 0%, #b47fd4 50%, #e8c7f0 100%); }
.img-ph--nondairy   { background: linear-gradient(135deg, #00824A 0%, #4caf7d 60%, #a8e6c1 100%); }
.img-ph--coffee     { background: linear-gradient(135deg, #3d1f0d 0%, #6f4e37 50%, #a07850 100%); }
.img-ph--matcha     { background: linear-gradient(135deg, #2e7d32 0%, #66bb6a 60%, #c8e6c9 100%); }
.img-ph--tea        { background: linear-gradient(135deg, #e65100 0%, #ff8a65 60%, #ffccbc 100%); }
.img-ph--food       { background: linear-gradient(135deg, #bf360c 0%, #e64a19 50%, #ff8a65 100%); }
.img-ph--atHome     { background: linear-gradient(135deg, #3e2723 0%, #6d4c41 60%, #a1887f 100%); }

/* ── ===== HEADER ===== ─────────────────────────────────────── */
.site-header {
  position: sticky; top: 0; z-index: 200;
  background: var(--forest);
  box-shadow: 0 2px 12px rgba(0,0,0,0.2);
}
.header-inner {
  display: flex; align-items: center; height: 72px; gap: 8px;
}
.header-logo {
  display: flex; align-items: center; gap: 10px;
  color: var(--cream); font-family: var(--font-head);
  font-size: 1.3rem; margin-right: 16px; flex-shrink: 0;
  transition: opacity var(--ease);
}
.header-logo:hover { opacity: 0.85; }
.header-logo-mark {
  width: 40px; height: 40px; background: var(--green);
  border-radius: 50%; display: flex; align-items: center;
  justify-content: center; font-size: 1.2rem; flex-shrink: 0;
}
.header-nav {
  display: flex; gap: 2px; flex: 1;
}
.header-nav a {
  color: rgba(255,255,255,0.88); padding: 8px 14px;
  border-radius: var(--r-sm); font-size: 0.9375rem; font-weight: 500;
  transition: background var(--ease), color var(--ease);
}
.header-nav a:hover  { background: rgba(255,255,255,0.12); color: var(--white); }
.header-nav a.active { background: rgba(255,255,255,0.18); color: var(--white); }
.header-actions { display: flex; gap: 8px; margin-left: auto; padding-left: 16px; }
.header-actions .btn { padding: 8px 20px; font-size: 0.875rem; }
.header-menu-btn {
  display: none; color: var(--white); padding: 8px; border-radius: var(--r-sm);
  align-items: center; justify-content: center;
  transition: background var(--ease);
}
.header-menu-btn:hover { background: rgba(255,255,255,0.12); }

/* Mobile nav drawer */
.mobile-nav {
  display: none; background: var(--forest-dark);
  border-top: 1px solid rgba(255,255,255,0.1);
}
.mobile-nav.open { display: block; }
.mobile-nav a {
  display: block; color: rgba(255,255,255,0.9); padding: 14px 24px;
  font-weight: 500; font-size: 1rem;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  transition: background var(--ease);
}
.mobile-nav a:hover { background: rgba(255,255,255,0.08); }
.mobile-nav-actions { padding: 16px 24px; display: flex; gap: 12px; }

/* ── ===== FOOTER ===== ─────────────────────────────────────── */
.site-footer { background: var(--forest); color: var(--white); }
.footer-main { padding: 64px 0 40px; }
.footer-grid {
  display: grid; grid-template-columns: repeat(5, 1fr); gap: 32px;
}
.footer-col-head {
  font-size: 0.8rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.08em; color: var(--cream); margin-bottom: 14px;
}
.footer-col-links a {
  display: block; color: rgba(255,255,255,0.7); font-size: 0.875rem;
  margin-bottom: 9px; transition: color var(--ease);
}
.footer-col-links a:hover { color: var(--white); }
.footer-col-trigger {
  display: none; width: 100%; text-align: left;
  color: var(--cream); font-size: 0.8rem; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.08em;
  padding: 16px 0; cursor: pointer; align-items: center; justify-content: space-between;
}
.footer-col-trigger svg { transition: transform var(--ease); flex-shrink: 0; }
.footer-col.open .footer-col-trigger svg { transform: rotate(180deg); }
.footer-social-row { margin-top: 48px; display: flex; align-items: center; gap: 12px; }
.footer-social-link {
  width: 38px; height: 38px; border-radius: 50%;
  background: rgba(255,255,255,0.1);
  display: flex; align-items: center; justify-content: center;
  color: var(--white); font-size: 1rem;
  transition: background var(--ease);
}
.footer-social-link:hover { background: var(--green); }
.footer-divider { border: none; border-top: 1px solid rgba(255,255,255,0.12); margin: 0; }
.footer-bottom {
  padding: 24px 0;
  display: flex; align-items: center; justify-content: space-between;
  flex-wrap: wrap; gap: 16px;
}
.footer-bottom-links { display: flex; gap: 20px; flex-wrap: wrap; }
.footer-bottom-links a { color: rgba(255,255,255,0.55); font-size: 0.8125rem; transition: color var(--ease); }
.footer-bottom-links a:hover { color: var(--white); }
.footer-copy { color: rgba(255,255,255,0.4); font-size: 0.8125rem; }

/* ── ===== COOKIE BANNER ===== ──────────────────────────────── */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 300;
  background: var(--white); border-top: 3px solid var(--cream);
  box-shadow: 0 -4px 30px rgba(0,0,0,0.12); padding: 20px 0;
  transition: transform 0.35s ease, opacity 0.35s ease;
}
.cookie-banner.hidden { transform: translateY(110%); opacity: 0; pointer-events: none; }
.cookie-inner { display: flex; align-items: center; gap: 20px; flex-wrap: wrap; }
.cookie-icon { font-size: 2.25rem; flex-shrink: 0; }
.cookie-text { flex: 1; min-width: 240px; }
.cookie-text h3 { font-size: 1.0625rem; margin-bottom: 4px; }
.cookie-text p { font-size: 0.875rem; color: var(--text-mid); }
.cookie-actions { display: flex; gap: 10px; align-items: center; flex-shrink: 0; }
.cookie-actions .btn { white-space: nowrap; }

/* ── ===== BREADCRUMB ===== ─────────────────────────────────── */
.breadcrumb { padding: 16px 0; }
.breadcrumb ol { display: flex; align-items: center; gap: 8px; font-size: 0.875rem; }
.breadcrumb li { display: flex; align-items: center; gap: 8px; }
.breadcrumb a { color: var(--text-mid); transition: color var(--ease); }
.breadcrumb a:hover { color: var(--green); }
.breadcrumb .sep { color: var(--text-light); }
.breadcrumb .current { color: var(--text); font-weight: 500; }

/* ── ===== CAROUSEL ===== ────────────────────────────────────── */
.carousel-wrap { position: relative; }
.carousel-viewport { overflow: hidden; border-radius: var(--r-md); }
.carousel-track {
  display: flex; gap: 20px;
  transition: transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.carousel-track .carousel-item { flex: 0 0 calc(25% - 15px); min-width: 0; }
.carousel-btn {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 44px; height: 44px; border-radius: 50%;
  background: var(--white); box-shadow: var(--shadow-md);
  display: flex; align-items: center; justify-content: center;
  color: var(--forest); z-index: 10; border: 2px solid var(--border);
  transition: all var(--ease);
}
.carousel-btn:hover { background: var(--green); color: var(--white); border-color: var(--green); transform: translateY(-50%) scale(1.05); }
.carousel-btn:disabled { opacity: 0.35; pointer-events: none; }
.carousel-btn--prev { left: -22px; }
.carousel-btn--next { right: -22px; }

/* ── ===== TABS ===== ────────────────────────────────────────── */
.tabs { }
.tab-list {
  display: flex; gap: 4px; border-bottom: 2px solid var(--border);
  overflow-x: auto; scrollbar-width: none; padding-bottom: 0;
}
.tab-list::-webkit-scrollbar { display: none; }
.tab-btn {
  padding: 12px 20px; font-weight: 600; font-size: 0.9375rem;
  color: var(--text-mid); border-radius: var(--r-sm) var(--r-sm) 0 0;
  border-bottom: 3px solid transparent; margin-bottom: -2px;
  transition: all var(--ease); white-space: nowrap; flex-shrink: 0;
}
.tab-btn:hover { color: var(--green); background: var(--green-light); }
.tab-btn.active { color: var(--green); border-bottom-color: var(--green); background: transparent; }
.tab-panel { display: none; padding: 32px 0; }
.tab-panel.active { display: block; }

/* ── ===== TOGGLE SWITCH ===== ──────────────────────────────── */
.toggle-group {
  display: inline-flex; background: rgba(255,255,255,0.1);
  border-radius: var(--r-xl); padding: 4px; gap: 2px;
}
.toggle-btn {
  padding: 9px 22px; border-radius: var(--r-xl);
  font-weight: 600; font-size: 0.9rem; color: rgba(255,255,255,0.7);
  transition: all var(--ease);
}
.toggle-btn.active {
  background: var(--white); color: var(--forest);
  box-shadow: var(--shadow-sm);
}

/* ── ===== GIFT CARD ===== ───────────────────────────────────── */
.giftcard {
  border-radius: var(--r-md); overflow: hidden;
  box-shadow: var(--shadow-sm); cursor: pointer;
  transition: transform var(--ease), box-shadow var(--ease);
}
.giftcard:hover { transform: translateY(-5px) rotate(-1deg); box-shadow: var(--shadow-md); }
.giftcard-img {
  aspect-ratio: 16/10; display: flex; align-items: center; justify-content: center;
  font-size: 2rem; font-weight: 700; color: rgba(255,255,255,0.9);
  font-family: var(--font-head); padding: 20px; text-align: center;
}
.giftcard-label { padding: 10px 12px; font-size: 0.875rem; font-weight: 500; }

/* ── ===== STORE CARD ===== ─────────────────────────────────── */
.store-card {
  background: var(--white); border-radius: var(--r-md);
  padding: 20px; border: 2px solid var(--border);
  transition: border-color var(--ease), box-shadow var(--ease);
  cursor: pointer;
}
.store-card:hover { border-color: var(--green); box-shadow: var(--shadow-sm); }
.store-card.selected { border-color: var(--green); background: var(--green-light); }
.store-name { font-weight: 700; font-size: 1rem; margin-bottom: 4px; }
.store-address { font-size: 0.875rem; color: var(--text-mid); margin-bottom: 8px; }
.store-hours { font-size: 0.8125rem; color: var(--green); font-weight: 600; margin-bottom: 10px; }
.store-features { display: flex; gap: 6px; flex-wrap: wrap; }
.store-feature {
  font-size: 0.75rem; padding: 3px 9px; border-radius: var(--r-xl);
  background: var(--cream-light); color: var(--text-mid); border: 1px solid var(--border);
}
.store-distance { font-size: 0.8125rem; color: var(--text-light); font-weight: 500; }

/* ── ===== TIER CARDS ===== ─────────────────────────────────── */
.tier-card {
  border-radius: var(--r-lg); padding: 36px 28px;
  text-align: center; position: relative; overflow: hidden;
}
.tier-card--green  { background: linear-gradient(145deg, #e6f4ee, #c1e8d4); color: var(--forest); }
.tier-card--gold   { background: linear-gradient(145deg, #fffbeb, #fce7a3); color: #5a4a00; }
.tier-card--reserve { background: linear-gradient(145deg, #32462F, #1a3019); color: var(--white); }
.tier-badge {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 6px 16px; border-radius: var(--r-xl); font-weight: 700;
  font-size: 0.875rem; margin-bottom: 16px;
}
.tier-card--green  .tier-badge { background: var(--green); color: var(--white); }
.tier-card--gold   .tier-badge { background: #c9a200; color: var(--white); }
.tier-card--reserve .tier-badge { background: var(--cream); color: var(--forest); }
.tier-stars { font-size: 0.875rem; margin-bottom: 20px; opacity: 0.8; }
.tier-benefits { text-align: left; }
.tier-benefits li { font-size: 0.9rem; padding: 8px 0; border-bottom: 1px solid rgba(0,0,0,0.07); display: flex; gap: 10px; }
.tier-card--reserve .tier-benefits li { border-bottom-color: rgba(255,255,255,0.1); }
.tier-benefits li:last-child { border-bottom: none; }
.tier-check { color: var(--green); font-weight: 700; flex-shrink: 0; }
.tier-card--reserve .tier-check { color: var(--cream); }

/* ── ===== ACCORDION ===== ──────────────────────────────────── */
.accordion-item { border-bottom: 1px solid var(--border); }
.accordion-trigger {
  display: flex; align-items: center; justify-content: space-between;
  width: 100%; padding: 20px 0; text-align: left; font-weight: 600; font-size: 1rem;
  transition: color var(--ease);
}
.accordion-trigger:hover { color: var(--green); }
.accordion-trigger svg { transition: transform var(--ease); flex-shrink: 0; }
.accordion-item.open .accordion-trigger svg { transform: rotate(180deg); }
.accordion-content { display: none; padding: 0 0 20px; color: var(--text-mid); }
.accordion-item.open .accordion-content { display: block; }

/* ── ===== FILTER PANEL ===== ────────────────────────────────── */
.filter-panel {
  position: fixed; top: 0; right: 0; bottom: 0; width: 320px;
  background: var(--white); box-shadow: var(--shadow-lg); z-index: 400;
  transform: translateX(100%); transition: transform 0.3s ease;
  display: flex; flex-direction: column;
}
.filter-panel.open { transform: translateX(0); }
.filter-overlay {
  position: fixed; inset: 0; background: rgba(0,0,0,0.4);
  z-index: 399; opacity: 0; pointer-events: none;
  transition: opacity 0.3s ease;
}
.filter-overlay.open { opacity: 1; pointer-events: all; }
.filter-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 20px 24px; border-bottom: 1px solid var(--border);
}
.filter-header h3 { font-size: 1.125rem; }
.filter-body { flex: 1; overflow-y: auto; padding: 24px; }
.filter-group { margin-bottom: 28px; }
.filter-group h4 { font-size: 0.875rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-mid); margin-bottom: 12px; }
.filter-check { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; font-size: 0.9375rem; cursor: pointer; }
.filter-check input { width: 18px; height: 18px; accent-color: var(--green); cursor: pointer; }
.filter-footer { padding: 16px 24px; border-top: 1px solid var(--border); display: flex; gap: 12px; }

/* ── ===== HOW IT WORKS ===== ────────────────────────────────── */
.how-step { text-align: center; padding: 0 16px; }
.how-step-num {
  width: 64px; height: 64px; border-radius: 50%;
  background: var(--green); color: var(--white);
  display: flex; align-items: center; justify-content: center;
  font-family: var(--font-head); font-size: 1.5rem;
  margin: 0 auto 20px;
}
.how-step h3 { font-size: 1.125rem; margin-bottom: 10px; }
.how-step p { font-size: 0.9375rem; color: var(--text-mid); }

/* ── ===== SEARCH INPUT ===== ────────────────────────────────── */
.search-box {
  position: relative;
  flex: 1; min-width: 0;
}
.search-input {
  width: 100%; padding: 14px 48px 14px 48px;
  border: 2px solid var(--border); border-radius: var(--r-xl);
  font-size: 1rem; background: var(--white);
  transition: border-color var(--ease), box-shadow var(--ease);
  outline: none;
}
.search-input:focus { border-color: var(--green); box-shadow: 0 0 0 3px rgba(0,130,74,0.15); }
.search-icon {
  position: absolute; left: 16px; top: 50%; transform: translateY(-50%);
  color: var(--text-light); pointer-events: none;
}
.search-clear {
  position: absolute; right: 14px; top: 50%; transform: translateY(-50%);
  color: var(--text-light); padding: 4px; border-radius: 50%;
  transition: all var(--ease); display: none;
}
.search-clear.visible { display: flex; }
.search-clear:hover { background: var(--cream-light); color: var(--text); }
.search-suggestions {
  position: absolute; top: calc(100% + 6px); left: 0; right: 0;
  background: var(--white); border-radius: var(--r-md);
  box-shadow: var(--shadow-lg); z-index: 50; overflow: hidden;
  display: none;
}
.search-suggestions.visible { display: block; }
.suggestion-item {
  display: flex; align-items: center; gap: 12px;
  padding: 12px 16px; cursor: pointer; font-size: 0.9375rem;
  transition: background var(--ease);
}
.suggestion-item:hover { background: var(--cream-light); }
.suggestion-icon { color: var(--text-light); flex-shrink: 0; }

/* ── ===== MAP PLACEHOLDER ===== ─────────────────────────────── */
.map-placeholder {
  width: 100%; height: 420px;
  background: linear-gradient(160deg, #c8d9c0 0%, #d4e8cc 40%, #b8ccb0 100%);
  border-radius: var(--r-lg); display: flex; align-items: center;
  justify-content: center; position: relative; overflow: hidden;
}
.map-grid {
  position: absolute; inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,0.3) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.3) 1px, transparent 1px);
  background-size: 40px 40px;
}
.map-pin {
  position: absolute; display: flex; flex-direction: column; align-items: center;
}
.map-pin-dot {
  width: 20px; height: 20px; background: var(--green);
  border-radius: 50% 50% 50% 0; transform: rotate(-45deg);
  border: 2px solid var(--white); box-shadow: var(--shadow-sm);
  cursor: pointer; transition: transform var(--ease);
}
.map-pin-dot:hover { transform: rotate(-45deg) scale(1.2); }
.map-pin-label {
  background: var(--white); padding: 4px 8px; border-radius: var(--r-sm);
  font-size: 0.75rem; font-weight: 600; white-space: nowrap;
  box-shadow: var(--shadow-sm); margin-top: 4px; transform: rotate(0deg);
}
.map-overlay-card {
  position: absolute; bottom: 20px; left: 20px;
  background: var(--white); border-radius: var(--r-md);
  padding: 16px 20px; box-shadow: var(--shadow-md); min-width: 240px;
}

/* ── ===== MENU SIDEBAR ===== ────────────────────────────────── */
.menu-layout { display: grid; grid-template-columns: 260px 1fr; gap: 40px; align-items: start; }
.menu-sidebar {
  background: var(--cream-light); border-radius: var(--r-lg);
  padding: 24px; position: sticky; top: 92px; max-height: calc(100vh - 112px); overflow-y: auto;
}
.menu-sidebar::-webkit-scrollbar { width: 4px; }
.menu-sidebar::-webkit-scrollbar-track { background: transparent; }
.menu-sidebar::-webkit-scrollbar-thumb { background: var(--cream-mid); border-radius: 2px; }
.sidebar-group { margin-bottom: 24px; }
.sidebar-group-head { font-size: 0.75rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-light); margin-bottom: 8px; padding: 0 8px; }
.sidebar-link {
  display: block; padding: 9px 12px; border-radius: var(--r-sm);
  font-size: 0.9375rem; color: var(--text-mid); transition: all var(--ease);
  font-weight: 500;
}
.sidebar-link:hover { background: var(--cream-mid); color: var(--forest); }
.sidebar-link.active { background: var(--green); color: var(--white); }

/* Menu item cards */
.menu-items-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 20px; }
.menu-item {
  background: var(--white); border-radius: var(--r-md); overflow: hidden;
  border: 1px solid var(--border); transition: all var(--ease); cursor: pointer;
}
.menu-item:hover { border-color: var(--green); box-shadow: var(--shadow-sm); transform: translateY(-3px); }
.menu-item-img {
  aspect-ratio: 1; display: flex; align-items: center;
  justify-content: center; font-size: 2.5rem;
}
.menu-item-info { padding: 12px; }
.menu-item-name { font-weight: 600; font-size: 0.9rem; margin-bottom: 2px; }
.menu-item-cal { font-size: 0.8rem; color: var(--text-light); }
.menu-section { margin-bottom: 56px; }
.menu-section-title {
  font-size: 1.5rem; margin-bottom: 20px; padding-bottom: 12px;
  border-bottom: 2px solid var(--border);
}

/* ── ===== UTILITY ===== ─────────────────────────────────────── */
.text-green  { color: var(--green); }
.text-forest { color: var(--forest); }
.text-cream  { color: var(--cream); }
.text-mid    { color: var(--text-mid); }
.text-light  { color: var(--text-light); }
.visually-hidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }
.flex        { display: flex; }
.flex-center { display: flex; align-items: center; }
.gap-8  { gap: 8px; }
.gap-12 { gap: 12px; }
.gap-16 { gap: 16px; }
.gap-24 { gap: 24px; }
.grid-2 { display: grid; grid-template-columns: repeat(2,1fr); gap: 24px; }
.grid-3 { display: grid; grid-template-columns: repeat(3,1fr); gap: 24px; }
.grid-4 { display: grid; grid-template-columns: repeat(4,1fr); gap: 24px; }
.mt-8  { margin-top: 8px; }
.mt-12 { margin-top: 12px; }
.mt-16 { margin-top: 16px; }
.mt-24 { margin-top: 24px; }
.mt-32 { margin-top: 32px; }
.mb-8  { margin-bottom: 8px; }
.mb-12 { margin-bottom: 12px; }
.mb-16 { margin-bottom: 16px; }
.mb-24 { margin-bottom: 24px; }
.mb-32 { margin-bottom: 32px; }
.rounded { border-radius: var(--r-lg); }
.overflow-hidden { overflow: hidden; }

/* ── ===== RESPONSIVE ===== ─────────────────────────────────── */
@media (max-width: 1200px) {
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .carousel-track .carousel-item { flex: 0 0 calc(33.333% - 14px); }
}

@media (max-width: 1024px) {
  .menu-layout { grid-template-columns: 1fr; }
  .menu-sidebar { position: static; max-height: none; }
  .grid-4 { grid-template-columns: repeat(2,1fr); }
}

@media (max-width: 768px) {
  .header-nav, .header-actions { display: none; }
  .header-menu-btn { display: flex; }
  h1 { font-size: clamp(1.75rem, 7vw, 2.5rem); }
  h2 { font-size: clamp(1.5rem, 5vw, 2rem); }
  .section { padding: 56px 0; }
  .section--lg { padding: 72px 0; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-col { border-bottom: 1px solid rgba(255,255,255,0.1); }
  .footer-col-head { display: none; }
  .footer-col-trigger { display: flex; }
  .footer-col-links { display: none; padding-bottom: 12px; }
  .footer-col.open .footer-col-links { display: block; }
  .footer-bottom { flex-direction: column; text-align: center; }
  .footer-bottom-links { justify-content: center; }
  .footer-social-row { justify-content: center; }
  .grid-3 { grid-template-columns: 1fr; }
  .grid-2 { grid-template-columns: 1fr; }
  .carousel-track .carousel-item { flex: 0 0 calc(50% - 10px); }
  .carousel-btn--prev { left: -10px; }
  .carousel-btn--next { right: -10px; }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .container--wide { padding: 0 16px; }
  .btn { padding: 11px 20px; }
  .carousel-track .carousel-item { flex: 0 0 calc(100% - 0px); }
  .cookie-inner { flex-direction: column; }
  .cookie-actions { width: 100%; justify-content: stretch; }
  .cookie-actions .btn { flex: 1; justify-content: center; }
  .filter-panel { width: 100%; }
}

/* ============================================================
   GreenBean Coffee — Global Styles
   ============================================================ */

@import url('https://fonts.googleapis.com/css2?family=DM+Serif+Display:ital@0;1&family=DM+Sans:wght@300;400;500;600;700&display=swap');

/* ── Variables ─────────────────────────────────────────────── */
:root {
  --green:        #00824A;
  --green-dark:   #006d3e;
  --green-light:  #e6f4ee;
  --forest:       #32462F;
  --forest-dark:  #253d22;
  --cream:        #F3CEA1;
  --cream-light:  #FDF6EE;
  --cream-mid:    #f5ddb8;
  --brown:        #6F4E37;
  --brown-light:  #c8a882;
  --white:        #FFFFFF;
  --text:         #1a1a1a;
  --text-mid:     #4a4a4a;
  --text-light:   #767676;
  --border:       #e5e0d8;
  --shadow-sm:    0 2px 8px rgba(0,0,0,0.07);
  --shadow-md:    0 4px 20px rgba(0,0,0,0.10);
  --shadow-lg:    0 8px 40px rgba(0,0,0,0.14);
  --r-sm:  8px;
  --r-md:  16px;
  --r-lg:  24px;
  --r-xl:  40px;
  --ease: 0.22s ease;
  --font-head: 'DM Serif Display', Georgia, serif;
  --font-body: 'DM Sans', system-ui, sans-serif;
}

/* ── Reset ─────────────────────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; font-size: 16px; }
body { font-family: var(--font-body); color: var(--text); background: var(--white); line-height: 1.6; -webkit-font-smoothing: antialiased; }
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; border: none; background: none; font-family: inherit; font-size: inherit; }
ul, ol { list-style: none; }
input, textarea { font-family: inherit; font-size: inherit; }
svg { display: block; }

/* ── Typography ────────────────────────────────────────────── */
h1, h2, h3, h4, h5 { font-family: var(--font-head); line-height: 1.15; }
h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.6rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 2.5vw, 1.875rem); }
h4 { font-size: 1.25rem; }
p { line-height: 1.75; }

/* ── Layout ────────────────────────────────────────────────── */
.container      { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
.container--wide { max-width: 1440px; margin: 0 auto; padding: 0 32px; }

/* ── Buttons ───────────────────────────────────────────────── */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 13px 28px; border-radius: var(--r-xl);
  font-weight: 700; font-size: 0.9375rem; font-family: var(--font-body);
  transition: all var(--ease); white-space: nowrap; cursor: pointer;
  line-height: 1; border: 2px solid transparent;
}
.btn--primary  { background: var(--green); color: var(--white); }
.btn--primary:hover  { background: var(--green-dark); transform: translateY(-2px); box-shadow: 0 6px 20px rgba(0,130,74,0.35); }
.btn--outline  { background: transparent; color: var(--green); border-color: var(--green); }
.btn--outline:hover  { background: var(--green); color: var(--white); }
.btn--dark     { background: var(--forest); color: var(--white); }
.btn--dark:hover     { background: var(--forest-dark); transform: translateY(-2px); }
.btn--white    { background: var(--white); color: var(--forest); }
.btn--white:hover    { background: var(--cream-light); transform: translateY(-2px); }
.btn--cream    { background: var(--cream); color: var(--forest); border-color: var(--cream); }
.btn--cream:hover    { background: var(--cream-mid); transform: translateY(-2px); }
.btn--outline-white { background: transparent; color: var(--white); border-color: rgba(255,255,255,0.7); }
.btn--outline-white:hover { background: rgba(255,255,255,0.15); }
.btn--sm  { padding: 9px 18px; font-size: 0.875rem; }
.btn--lg  { padding: 16px 36px; font-size: 1.0625rem; }
.btn--icon { padding: 12px; border-radius: 50%; }

/* ── Sections ──────────────────────────────────────────────── */
.section { padding: 80px 0; }
.section--sm { padding: 48px 0; }
.section--lg { padding: 112px 0; }
.section--cream { background: var(--cream-light); }
.section--forest { background: var(--forest); color: var(--white); }
.section--green { background: var(--green); color: var(--white); }
.section-label {
  display: inline-block; font-size: 0.75rem; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.1em; color: var(--green);
  margin-bottom: 10px;
}
.section-label--light { color: var(--cream); }
.section-header { text-align: center; margin-bottom: 56px; }
.section-header p { color: var(--text-mid); max-width: 560px; margin: 12px auto 0; }
.section-header--light p { color: rgba(255,255,255,0.75); }
.section-header--left { text-align: left; }
.section-header--left p { margin-left: 0; }

/* ── Cards ─────────────────────────────────────────────────── */
.card {
  background: var(--white); border-radius: var(--r-lg);
  box-shadow: var(--shadow-sm); overflow: hidden;
  transition: transform var(--ease), box-shadow var(--ease);
}
.card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.card-img { width: 100%; aspect-ratio: 4/3; overflow: hidden; }
.card-body { padding: 20px; }
.card-title { font-size: 1rem; font-weight: 600; margin-bottom: 4px; }
.card-desc { font-size: 0.875rem; color: var(--text-mid); }

/* ── Badges ─────────────────────────────────────────────────── */
.badge {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 4px 12px; border-radius: var(--r-xl);
  font-size: 0.75rem; font-weight: 700; letter-spacing: 0.03em;
}
.badge--green  { background: var(--green-light); color: var(--green-dark); }
.badge--cream  { background: var(--cream); color: var(--forest); }
.badge--forest { background: var(--forest); color: var(--white); }
.badge--new    { background: #FFF0D4; color: #A05C00; }

/* ── Image Placeholders ─────────────────────────────────────── */
.img-ph {
  width: 100%; height: 100%; min-height: 200px;
  display: flex; align-items: center; justify-content: center;
  font-size: 3.5rem; border-radius: inherit;
}
.img-ph--hero       { background: linear-gradient(135deg, #1a3a2a 0%, #2d5a3d 50%, #00824A 100%); }
.img-ph--citrus     { background: linear-gradient(135deg, #ff9b00 0%, #ffcc44 60%, #ffe580 100%); }
.img-ph--afternoon  { background: linear-gradient(135deg, #6F4E37 0%, #c8956c 60%, #f3cea1 100%); }
.img-ph--ai         { background: linear-gradient(135deg, #1a3a5c 0%, #2d6a9f 100%); }
.img-ph--mango      { background: linear-gradient(135deg, #f7a800 0%, #ff6b35 60%, #ffcc44 100%); }
.img-ph--spring     { background: linear-gradient(135deg, #7c4dbe 0%, #b47fd4 50%, #e8c7f0 100%); }
.img-ph--nondairy   { background: linear-gradient(135deg, #00824A 0%, #4caf7d 60%, #a8e6c1 100%); }
.img-ph--coffee     { background: linear-gradient(135deg, #3d1f0d 0%, #6f4e37 50%, #a07850 100%); }
.img-ph--matcha     { background: linear-gradient(135deg, #2e7d32 0%, #66bb6a 60%, #c8e6c9 100%); }
.img-ph--tea        { background: linear-gradient(135deg, #e65100 0%, #ff8a65 60%, #ffccbc 100%); }
.img-ph--food       { background: linear-gradient(135deg, #bf360c 0%, #e64a19 50%, #ff8a65 100%); }
.img-ph--atHome     { background: linear-gradient(135deg, #3e2723 0%, #6d4c41 60%, #a1887f 100%); }

/* ── ===== HEADER ===== ─────────────────────────────────────── */
.site-header {
  position: sticky; top: 0; z-index: 200;
  background: var(--forest);
  box-shadow: 0 2px 12px rgba(0,0,0,0.2);
}
.header-inner {
  display: flex; align-items: center; height: 72px; gap: 8px;
}
.header-logo {
  display: flex; align-items: center; gap: 10px;
  color: var(--cream); font-family: var(--font-head);
  font-size: 1.3rem; margin-right: 16px; flex-shrink: 0;
  transition: opacity var(--ease);
}
.header-logo:hover { opacity: 0.85; }
.header-logo-mark {
  width: 40px; height: 40px; background: var(--green);
  border-radius: 50%; display: flex; align-items: center;
  justify-content: center; font-size: 1.2rem; flex-shrink: 0;
}
.header-nav {
  display: flex; gap: 2px; flex: 1;
}
.header-nav a {
  color: rgba(255,255,255,0.88); padding: 8px 14px;
  border-radius: var(--r-sm); font-size: 0.9375rem; font-weight: 500;
  transition: background var(--ease), color var(--ease);
}
.header-nav a:hover  { background: rgba(255,255,255,0.12); color: var(--white); }
.header-nav a.active { background: rgba(255,255,255,0.18); color: var(--white); }
.header-actions { display: flex; gap: 8px; margin-left: auto; padding-left: 16px; }
.header-actions .btn { padding: 8px 20px; font-size: 0.875rem; }
.header-menu-btn {
  display: none; color: var(--white); padding: 8px; border-radius: var(--r-sm);
  align-items: center; justify-content: center;
  transition: background var(--ease);
}
.header-menu-btn:hover { background: rgba(255,255,255,0.12); }

/* Mobile nav drawer */
.mobile-nav {
  display: none; background: var(--forest-dark);
  border-top: 1px solid rgba(255,255,255,0.1);
}
.mobile-nav.open { display: block; }
.mobile-nav a {
  display: block; color: rgba(255,255,255,0.9); padding: 14px 24px;
  font-weight: 500; font-size: 1rem;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  transition: background var(--ease);
}
.mobile-nav a:hover { background: rgba(255,255,255,0.08); }
.mobile-nav-actions { padding: 16px 24px; display: flex; gap: 12px; }

/* ── ===== FOOTER ===== ─────────────────────────────────────── */
.site-footer { background: var(--forest); color: var(--white); }
.footer-main { padding: 64px 0 40px; }
.footer-grid {
  display: grid; grid-template-columns: repeat(5, 1fr); gap: 32px;
}
.footer-col-head {
  font-size: 0.8rem; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.08em; color: var(--cream); margin-bottom: 14px;
}
.footer-col-links a {
  display: block; color: rgba(255,255,255,0.7); font-size: 0.875rem;
  margin-bottom: 9px; transition: color var(--ease);
}
.footer-col-links a:hover { color: var(--white); }
.footer-col-trigger {
  display: none; width: 100%; text-align: left;
  color: var(--cream); font-size: 0.8rem; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.08em;
  padding: 16px 0; cursor: pointer; align-items: center; justify-content: space-between;
}
.footer-col-trigger svg { transition: transform var(--ease); flex-shrink: 0; }
.footer-col.open .footer-col-trigger svg { transform: rotate(180deg); }
.footer-social-row { margin-top: 48px; display: flex; align-items: center; gap: 12px; }
.footer-social-link {
  width: 38px; height: 38px; border-radius: 50%;
  background: rgba(255,255,255,0.1);
  display: flex; align-items: center; justify-content: center;
  color: var(--white); font-size: 1rem;
  transition: background var(--ease);
}
.footer-social-link:hover { background: var(--green); }
.footer-divider { border: none; border-top: 1px solid rgba(255,255,255,0.12); margin: 0; }
.footer-bottom {
  padding: 24px 0;
  display: flex; align-items: center; justify-content: space-between;
  flex-wrap: wrap; gap: 16px;
}
.footer-bottom-links { display: flex; gap: 20px; flex-wrap: wrap; }
.footer-bottom-links a { color: rgba(255,255,255,0.55); font-size: 0.8125rem; transition: color var(--ease); }
.footer-bottom-links a:hover { color: var(--white); }
.footer-copy { color: rgba(255,255,255,0.4); font-size: 0.8125rem; }

/* ── ===== COOKIE BANNER ===== ──────────────────────────────── */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 300;
  background: var(--white); border-top: 3px solid var(--cream);
  box-shadow: 0 -4px 30px rgba(0,0,0,0.12); padding: 20px 0;
  transition: transform 0.35s ease, opacity 0.35s ease;
}
.cookie-banner.hidden { transform: translateY(110%); opacity: 0; pointer-events: none; }
.cookie-inner { display: flex; align-items: center; gap: 20px; flex-wrap: wrap; }
.cookie-icon { font-size: 2.25rem; flex-shrink: 0; }
.cookie-text { flex: 1; min-width: 240px; }
.cookie-text h3 { font-size: 1.0625rem; margin-bottom: 4px; }
.cookie-text p { font-size: 0.875rem; color: var(--text-mid); }
.cookie-actions { display: flex; gap: 10px; align-items: center; flex-shrink: 0; }
.cookie-actions .btn { white-space: nowrap; }

/* ── ===== BREADCRUMB ===== ─────────────────────────────────── */
.breadcrumb { padding: 16px 0; }
.breadcrumb ol { display: flex; align-items: center; gap: 8px; font-size: 0.875rem; }
.breadcrumb li { display: flex; align-items: center; gap: 8px; }
.breadcrumb a { color: var(--text-mid); transition: color var(--ease); }
.breadcrumb a:hover { color: var(--green); }
.breadcrumb .sep { color: var(--text-light); }
.breadcrumb .current { color: var(--text); font-weight: 500; }

/* ── ===== CAROUSEL ===== ────────────────────────────────────── */
.carousel-wrap { position: relative; }
.carousel-viewport { overflow: hidden; border-radius: var(--r-md); }
.carousel-track {
  display: flex; gap: 20px;
  transition: transform 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}
.carousel-track .carousel-item { flex: 0 0 calc(25% - 15px); min-width: 0; }
.carousel-btn {
  position: absolute; top: 50%; transform: translateY(-50%);
  width: 44px; height: 44px; border-radius: 50%;
  background: var(--white); box-shadow: var(--shadow-md);
  display: flex; align-items: center; justify-content: center;
  color: var(--forest); z-index: 10; border: 2px solid var(--border);
  transition: all var(--ease);
}
.carousel-btn:hover { background: var(--green); color: var(--white); border-color: var(--green); transform: translateY(-50%) scale(1.05); }
.carousel-btn:disabled { opacity: 0.35; pointer-events: none; }
.carousel-btn--prev { left: -22px; }
.carousel-btn--next { right: -22px; }

/* ── ===== TABS ===== ────────────────────────────────────────── */
.tabs { }
.tab-list {
  display: flex; gap: 4px; border-bottom: 2px solid var(--border);
  overflow-x: auto; scrollbar-width: none; padding-bottom: 0;
}
.tab-list::-webkit-scrollbar { display: none; }
.tab-btn {
  padding: 12px 20px; font-weight: 600; font-size: 0.9375rem;
  color: var(--text-mid); border-radius: var(--r-sm) var(--r-sm) 0 0;
  border-bottom: 3px solid transparent; margin-bottom: -2px;
  transition: all var(--ease); white-space: nowrap; flex-shrink: 0;
}
.tab-btn:hover { color: var(--green); background: var(--green-light); }
.tab-btn.active { color: var(--green); border-bottom-color: var(--green); background: transparent; }
.tab-panel { display: none; padding: 32px 0; }
.tab-panel.active { display: block; }

/* ── ===== TOGGLE SWITCH ===== ──────────────────────────────── */
.toggle-group {
  display: inline-flex; background: rgba(255,255,255,0.1);
  border-radius: var(--r-xl); padding: 4px; gap: 2px;
}
.toggle-btn {
  padding: 9px 22px; border-radius: var(--r-xl);
  font-weight: 600; font-size: 0.9rem; color: rgba(255,255,255,0.7);
  transition: all var(--ease);
}
.toggle-btn.active {
  background: var(--white); color: var(--forest);
  box-shadow: var(--shadow-sm);
}

/* ── ===== GIFT CARD ===== ───────────────────────────────────── */
.giftcard {
  border-radius: var(--r-md); overflow: hidden;
  box-shadow: var(--shadow-sm); cursor: pointer;
  transition: transform var(--ease), box-shadow var(--ease);
}
.giftcard:hover { transform: translateY(-5px) rotate(-1deg); box-shadow: var(--shadow-md); }
.giftcard-img {
  aspect-ratio: 16/10; display: flex; align-items: center; justify-content: center;
  font-size: 2rem; font-weight: 700; color: rgba(255,255,255,0.9);
  font-family: var(--font-head); padding: 20px; text-align: center;
}
.giftcard-label { padding: 10px 12px; font-size: 0.875rem; font-weight: 500; }

/* ── ===== STORE CARD ===== ─────────────────────────────────── */
.store-card {
  background: var(--white); border-radius: var(--r-md);
  padding: 20px; border: 2px solid var(--border);
  transition: border-color var(--ease), box-shadow var(--ease);
  cursor: pointer;
}
.store-card:hover { border-color: var(--green); box-shadow: var(--shadow-sm); }
.store-card.selected { border-color: var(--green); background: var(--green-light); }
.store-name { font-weight: 700; font-size: 1rem; margin-bottom: 4px; }
.store-address { font-size: 0.875rem; color: var(--text-mid); margin-bottom: 8px; }
.store-hours { font-size: 0.8125rem; color: var(--green); font-weight: 600; margin-bottom: 10px; }
.store-features { display: flex; gap: 6px; flex-wrap: wrap; }
.store-feature {
  font-size: 0.75rem; padding: 3px 9px; border-radius: var(--r-xl);
  background: var(--cream-light); color: var(--text-mid); border: 1px solid var(--border);
}
.store-distance { font-size: 0.8125rem; color: var(--text-light); font-weight: 500; }

/* ── ===== TIER CARDS ===== ─────────────────────────────────── */
.tier-card {
  border-radius: var(--r-lg); padding: 36px 28px;
  text-align: center; position: relative; overflow: hidden;
}
.tier-card--green  { background: linear-gradient(145deg, #e6f4ee, #c1e8d4); color: var(--forest); }
.tier-card--gold   { background: linear-gradient(145deg, #fffbeb, #fce7a3); color: #5a4a00; }
.tier-card--reserve { background: linear-gradient(145deg, #32462F, #1a3019); color: var(--white); }
.tier-badge {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 6px 16px; border-radius: var(--r-xl); font-weight: 700;
  font-size: 0.875rem; margin-bottom: 16px;
}
.tier-card--green  .tier-badge { background: var(--green); color: var(--white); }
.tier-card--gold   .tier-badge { background: #c9a200; color: var(--white); }
.tier-card--reserve .tier-badge { background: var(--cream); color: var(--forest); }
.tier-stars { font-size: 0.875rem; margin-bottom: 20px; opacity: 0.8; }
.tier-benefits { text-align: left; }
.tier-benefits li { font-size: 0.9rem; padding: 8px 0; border-bottom: 1px solid rgba(0,0,0,0.07); display: flex; gap: 10px; }
.tier-card--reserve .tier-benefits li { border-bottom-color: rgba(255,255,255,0.1); }
.tier-benefits li:last-child { border-bottom: none; }
.tier-check { color: var(--green); font-weight: 700; flex-shrink: 0; }
.tier-card--reserve .tier-check { color: var(--cream); }

/* ── ===== ACCORDION ===== ──────────────────────────────────── */
.accordion-item { border-bottom: 1px solid var(--border); }
.accordion-trigger {
  display: flex; align-items: center; justify-content: space-between;
  width: 100%; padding: 20px 0; text-align: left; font-weight: 600; font-size: 1rem;
  transition: color var(--ease);
}
.accordion-trigger:hover { color: var(--green); }
.accordion-trigger svg { transition: transform var(--ease); flex-shrink: 0; }
.accordion-item.open .accordion-trigger svg { transform: rotate(180deg); }
.accordion-content { display: none; padding: 0 0 20px; color: var(--text-mid); }
.accordion-item.open .accordion-content { display: block; }

/* ── ===== FILTER PANEL ===== ────────────────────────────────── */
.filter-panel {
  position: fixed; top: 0; right: 0; bottom: 0; width: 320px;
  background: var(--white); box-shadow: var(--shadow-lg); z-index: 400;
  transform: translateX(100%); transition: transform 0.3s ease;
  display: flex; flex-direction: column;
}
.filter-panel.open { transform: translateX(0); }
.filter-overlay {
  position: fixed; inset: 0; background: rgba(0,0,0,0.4);
  z-index: 399; opacity: 0; pointer-events: none;
  transition: opacity 0.3s ease;
}
.filter-overlay.open { opacity: 1; pointer-events: all; }
.filter-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: 20px 24px; border-bottom: 1px solid var(--border);
}
.filter-header h3 { font-size: 1.125rem; }
.filter-body { flex: 1; overflow-y: auto; padding: 24px; }
.filter-group { margin-bottom: 28px; }
.filter-group h4 { font-size: 0.875rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-mid); margin-bottom: 12px; }
.filter-check { display: flex; align-items: center; gap: 10px; margin-bottom: 10px; font-size: 0.9375rem; cursor: pointer; }
.filter-check input { width: 18px; height: 18px; accent-color: var(--green); cursor: pointer; }
.filter-footer { padding: 16px 24px; border-top: 1px solid var(--border); display: flex; gap: 12px; }

/* ── ===== HOW IT WORKS ===== ────────────────────────────────── */
.how-step { text-align: center; padding: 0 16px; }
.how-step-num {
  width: 64px; height: 64px; border-radius: 50%;
  background: var(--green); color: var(--white);
  display: flex; align-items: center; justify-content: center;
  font-family: var(--font-head); font-size: 1.5rem;
  margin: 0 auto 20px;
}
.how-step h3 { font-size: 1.125rem; margin-bottom: 10px; }
.how-step p { font-size: 0.9375rem; color: var(--text-mid); }

/* ── ===== SEARCH INPUT ===== ────────────────────────────────── */
.search-box {
  position: relative;
  flex: 1; min-width: 0;
}
.search-input {
  width: 100%; padding: 14px 48px 14px 48px;
  border: 2px solid var(--border); border-radius: var(--r-xl);
  font-size: 1rem; background: var(--white);
  transition: border-color var(--ease), box-shadow var(--ease);
  outline: none;
}
.search-input:focus { border-color: var(--green); box-shadow: 0 0 0 3px rgba(0,130,74,0.15); }
.search-icon {
  position: absolute; left: 16px; top: 50%; transform: translateY(-50%);
  color: var(--text-light); pointer-events: none;
}
.search-clear {
  position: absolute; right: 14px; top: 50%; transform: translateY(-50%);
  color: var(--text-light); padding: 4px; border-radius: 50%;
  transition: all var(--ease); display: none;
}
.search-clear.visible { display: flex; }
.search-clear:hover { background: var(--cream-light); color: var(--text); }
.search-suggestions {
  position: absolute; top: calc(100% + 6px); left: 0; right: 0;
  background: var(--white); border-radius: var(--r-md);
  box-shadow: var(--shadow-lg); z-index: 50; overflow: hidden;
  display: none;
}
.search-suggestions.visible { display: block; }
.suggestion-item {
  display: flex; align-items: center; gap: 12px;
  padding: 12px 16px; cursor: pointer; font-size: 0.9375rem;
  transition: background var(--ease);
}
.suggestion-item:hover { background: var(--cream-light); }
.suggestion-icon { color: var(--text-light); flex-shrink: 0; }

/* ── ===== MAP PLACEHOLDER ===== ─────────────────────────────── */
.map-placeholder {
  width: 100%; height: 420px;
  background: linear-gradient(160deg, #c8d9c0 0%, #d4e8cc 40%, #b8ccb0 100%);
  border-radius: var(--r-lg); display: flex; align-items: center;
  justify-content: center; position: relative; overflow: hidden;
}
.map-grid {
  position: absolute; inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,0.3) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.3) 1px, transparent 1px);
  background-size: 40px 40px;
}
.map-pin {
  position: absolute; display: flex; flex-direction: column; align-items: center;
}
.map-pin-dot {
  width: 20px; height: 20px; background: var(--green);
  border-radius: 50% 50% 50% 0; transform: rotate(-45deg);
  border: 2px solid var(--white); box-shadow: var(--shadow-sm);
  cursor: pointer; transition: transform var(--ease);
}
.map-pin-dot:hover { transform: rotate(-45deg) scale(1.2); }
.map-pin-label {
  background: var(--white); padding: 4px 8px; border-radius: var(--r-sm);
  font-size: 0.75rem; font-weight: 600; white-space: nowrap;
  box-shadow: var(--shadow-sm); margin-top: 4px; transform: rotate(0deg);
}
.map-overlay-card {
  position: absolute; bottom: 20px; left: 20px;
  background: var(--white); border-radius: var(--r-md);
  padding: 16px 20px; box-shadow: var(--shadow-md); min-width: 240px;
}

/* ── ===== MENU SIDEBAR ===== ────────────────────────────────── */
.menu-layout { display: grid; grid-template-columns: 260px 1fr; gap: 40px; align-items: start; }
.menu-sidebar {
  background: var(--cream-light); border-radius: var(--r-lg);
  padding: 24px; position: sticky; top: 92px; max-height: calc(100vh - 112px); overflow-y: auto;
}
.menu-sidebar::-webkit-scrollbar { width: 4px; }
.menu-sidebar::-webkit-scrollbar-track { background: transparent; }
.menu-sidebar::-webkit-scrollbar-thumb { background: var(--cream-mid); border-radius: 2px; }
.sidebar-group { margin-bottom: 24px; }
.sidebar-group-head { font-size: 0.75rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-light); margin-bottom: 8px; padding: 0 8px; }
.sidebar-link {
  display: block; padding: 9px 12px; border-radius: var(--r-sm);
  font-size: 0.9375rem; color: var(--text-mid); transition: all var(--ease);
  font-weight: 500;
}
.sidebar-link:hover { background: var(--cream-mid); color: var(--forest); }
.sidebar-link.active { background: var(--green); color: var(--white); }

/* Menu item cards */
.menu-items-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 20px; }
.menu-item {
  background: var(--white); border-radius: var(--r-md); overflow: hidden;
  border: 1px solid var(--border); transition: all var(--ease); cursor: pointer;
}
.menu-item:hover { border-color: var(--green); box-shadow: var(--shadow-sm); transform: translateY(-3px); }
.menu-item-img {
  aspect-ratio: 1; display: flex; align-items: center;
  justify-content: center; font-size: 2.5rem;
}
.menu-item-info { padding: 12px; }
.menu-item-name { font-weight: 600; font-size: 0.9rem; margin-bottom: 2px; }
.menu-item-cal { font-size: 0.8rem; color: var(--text-light); }
.menu-section { margin-bottom: 56px; }
.menu-section-title {
  font-size: 1.5rem; margin-bottom: 20px; padding-bottom: 12px;
  border-bottom: 2px solid var(--border);
}

/* ── ===== UTILITY ===== ─────────────────────────────────────── */
.text-green  { color: var(--green); }
.text-forest { color: var(--forest); }
.text-cream  { color: var(--cream); }
.text-mid    { color: var(--text-mid); }
.text-light  { color: var(--text-light); }
.visually-hidden { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0,0,0,0); }
.flex        { display: flex; }
.flex-center { display: flex; align-items: center; }
.gap-8  { gap: 8px; }
.gap-12 { gap: 12px; }
.gap-16 { gap: 16px; }
.gap-24 { gap: 24px; }
.grid-2 { display: grid; grid-template-columns: repeat(2,1fr); gap: 24px; }
.grid-3 { display: grid; grid-template-columns: repeat(3,1fr); gap: 24px; }
.grid-4 { display: grid; grid-template-columns: repeat(4,1fr); gap: 24px; }
.mt-8  { margin-top: 8px; }
.mt-12 { margin-top: 12px; }
.mt-16 { margin-top: 16px; }
.mt-24 { margin-top: 24px; }
.mt-32 { margin-top: 32px; }
.mb-8  { margin-bottom: 8px; }
.mb-12 { margin-bottom: 12px; }
.mb-16 { margin-bottom: 16px; }
.mb-24 { margin-bottom: 24px; }
.mb-32 { margin-bottom: 32px; }
.rounded { border-radius: var(--r-lg); }
.overflow-hidden { overflow: hidden; }

/* ── ===== RESPONSIVE ===== ─────────────────────────────────── */
@media (max-width: 1200px) {
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .carousel-track .carousel-item { flex: 0 0 calc(33.333% - 14px); }
}

@media (max-width: 1024px) {
  .menu-layout { grid-template-columns: 1fr; }
  .menu-sidebar { position: static; max-height: none; }
  .grid-4 { grid-template-columns: repeat(2,1fr); }
}

@media (max-width: 768px) {
  .header-nav, .header-actions { display: none; }
  .header-menu-btn { display: flex; }
  h1 { font-size: clamp(1.75rem, 7vw, 2.5rem); }
  h2 { font-size: clamp(1.5rem, 5vw, 2rem); }
  .section { padding: 56px 0; }
  .section--lg { padding: 72px 0; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-col { border-bottom: 1px solid rgba(255,255,255,0.1); }
  .footer-col-head { display: none; }
  .footer-col-trigger { display: flex; }
  .footer-col-links { display: none; padding-bottom: 12px; }
  .footer-col.open .footer-col-links { display: block; }
  .footer-bottom { flex-direction: column; text-align: center; }
  .footer-bottom-links { justify-content: center; }
  .footer-social-row { justify-content: center; }
  .grid-3 { grid-template-columns: 1fr; }
  .grid-2 { grid-template-columns: 1fr; }
  .carousel-track .carousel-item { flex: 0 0 calc(50% - 10px); }
  .carousel-btn--prev { left: -10px; }
  .carousel-btn--next { right: -10px; }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .container--wide { padding: 0 16px; }
  .btn { padding: 11px 20px; }
  .carousel-track .carousel-item { flex: 0 0 calc(100% - 0px); }
  .cookie-inner { flex-direction: column; }
  .cookie-actions { width: 100%; justify-content: stretch; }
  .cookie-actions .btn { flex: 1; justify-content: center; }
  .filter-panel { width: 100%; }
}

